[CmdletBinding()]
param(
    [Parameter(Mandatory=$true)][string]$ProjectPath,
    [Parameter(Mandatory=$true)][string]$PilotPlanPath,
    [Parameter(Mandatory=$true)][string]$ProvenancePath,
    [string]$UnityPath='H:\UnityEditor\2022.3.30f1c1\Editor\Unity.exe',
    [switch]$BindingSmokeOnly
)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
if([string]::IsNullOrWhiteSpace($ProjectPath)-or-not[IO.Path]::IsPathRooted($ProjectPath)){throw 'PR1B v2 pre-pilot requires an explicit absolute ProjectPath.'};$ProjectPath=[IO.Path]::GetFullPath($ProjectPath)
if($BindingSmokeOnly){Write-Output("BINDING-SMOKE-PASSED|Run-Gate13RPR1BPrePilotV2|$ProjectPath");exit 0}
$PilotPlanPath=[IO.Path]::GetFullPath($PilotPlanPath);$ProvenancePath=[IO.Path]::GetFullPath($ProvenancePath);$UnityPath=[IO.Path]::GetFullPath($UnityPath)
Import-Module (Join-Path $ProjectPath 'Research\Gate13RPR1BOrderEffectPreparationV2.psm1') -Force
$plan=Read-Gate13RPR1BV2Json $PilotPlanPath;$provenance=Read-Gate13RPR1BV2Json $ProvenancePath;Assert-Gate13RPR1BV2PlanIdentity $plan
$root=[IO.Path]::GetFullPath((Join-Path $ProjectPath ([string]$plan.paths.verificationRootRelativePath).Replace('/','\')));$base=[IO.Path]::GetFullPath((Join-Path $ProjectPath 'Research\Verification\Gate12R_ProcessReuse_5pct'))
if(-not$root.StartsWith($base.TrimEnd('\')+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'PR1B v2 verification root is outside versioned Gate12R containment.'};if(Test-Path $root){throw "Create-new PR1B v2 verification root exists: $root"}
$pilotRoot=Join-Path $ProjectPath ([string]$plan.paths.pilotRootRelativePath).Replace('/','\');$formalRoot=Join-Path $ProjectPath ([string]$plan.paths.reservedFormalRootRelativePath).Replace('/','\')
if(Test-Path $pilotRoot){throw 'PR1B v2 pilot root must be absent during pre-pilot.'};if(Test-Path $formalRoot){throw 'Reserved formal root must be absent.'};if(@(Get-Process -Name Unity -ErrorAction SilentlyContinue).Count-or(Test-Path (Join-Path $ProjectPath 'Temp\UnityLockfile'))){throw 'Unity must be closed and unlocked before PR1B v2 pre-pilot.'}
foreach($binding in @($provenance.boundFiles)){$path=Join-Path $ProjectPath ([string]$binding.relativePath).Replace('/','\');if(-not(Test-Path $path)-or(Get-Gate13RPR1BV2LowerSha256 $path)-ne[string]$binding.sha256){throw "Pre-pilot provenance binding failed: $($binding.relativePath)"}}
New-Item -ItemType Directory -Path $root -Force|Out-Null;New-Item -ItemType Directory -Path (Join-Path $root 'Orchestration') -Force|Out-Null
$winps='C:\WINDOWS\System32\WindowsPowerShell\v1.0\powershell.exe';$native=@('C:\Users\bdscy\Documents\WindowsPowerShell\Modules','C:\Program Files\WindowsPowerShell\Modules','C:\WINDOWS\System32\WindowsPowerShell\v1.0\Modules')-join';'
function Invoke-Step([string]$Name,[string]$Script,[string[]]$Arguments){$stdout=Join-Path $root ('Orchestration\'+$Name+'.stdout.log');$stderr=Join-Path $root ('Orchestration\'+$Name+'.stderr.log');$old=$env:PSModulePath;try{$env:PSModulePath=$native;&$winps -NoProfile -ExecutionPolicy Bypass -File $Script @Arguments 1>$stdout 2>$stderr;$exit=[int]$LASTEXITCODE}finally{$env:PSModulePath=$old};if($exit-ne0){throw "$Name failed: exit=$exit stderr=$stderr"}}
function Write-Checkpoint([string]$Status,[string]$Message){$value=[ordered]@{schemaVersion=2;checkpointKind='gate13r-pr1b-v2-prepilot-checkpoint-v1';savedAtUtc=[DateTime]::UtcNow.ToString('o');status=$Status;message=$Message;pilotPlanSha256=Get-Gate13RPR1BV2LowerSha256 $PilotPlanPath;provenanceSha256=Get-Gate13RPR1BV2LowerSha256 $ProvenancePath;formalCampaign=$false;gate13rFormalAuthorized=$false};Write-Gate13RPR1BV2AtomicUtf8NoBomJson -Path (Join-Path $root 'checkpoint.json') -Value $value -Depth 15}
function Write-Partial([string]$Status){$files=@(Get-ChildItem -LiteralPath $root -Recurse -File -Force|Where-Object{$_.Name-notlike'*.tmp-*' -and$_.Name-ne'partial-output-manifest.json'});$rows=@($files|ForEach-Object{[pscustomobject][ordered]@{relativePath=Get-Gate13RPR1BV2ProjectRelativePath $ProjectPath $_.FullName;rawBytes=[long]$_.Length;sha256=Get-Gate13RPR1BV2LowerSha256 $_.FullName}});Write-Gate13RPR1BV2AtomicUtf8NoBomJson -Path (Join-Path $root 'partial-output-manifest.json') -Value ([ordered]@{schemaVersion=2;manifestKind='gate13r-pr1b-v2-prepilot-partial-output-manifest-v1';status=$Status;savedAtUtc=[DateTime]::UtcNow.ToString('o');fileCount=$rows.Count;files=$rows;formalCampaign=$false}) -Depth 40}
try{
 $receipt=[ordered]@{schemaVersion=2;receiptKind='gate13r-pr1b-v2-prepilot-execution-receipt-v1';createdAtUtc=[DateTime]::UtcNow.ToString('o');verificationRoot=$root;pilotPlanSha256=Get-Gate13RPR1BV2LowerSha256 $PilotPlanPath;provenanceSha256=Get-Gate13RPR1BV2LowerSha256 $ProvenancePath;unitySha256=Get-Gate13RPR1BV2LowerSha256 $UnityPath;nonFormal=$true;formalCampaign=$false;gate13rFormalAuthorized=$false};Write-Gate13RPR1BV2AtomicUtf8NoBomJson -Path (Join-Path $root 'execution-receipt.json') -Value $receipt -Depth 15;Write-Checkpoint 'started' $null
 Invoke-Step '01-static-unit' (Join-Path $ProjectPath 'Research\Verification\Run-Gate13RPR1BStaticUnitV2.ps1') @('-ProjectPath',$ProjectPath,'-VerificationRoot',$root,'-PilotPlanPath',$PilotPlanPath,'-ProvenancePath',$ProvenancePath);Write-Checkpoint 'static-unit-passed' $null
 Invoke-Step '02-compile' (Join-Path $ProjectPath 'Research\Verification\Run-Gate12RCompileV4.ps1') @('-ProjectPath',$ProjectPath,'-VerificationRoot',$root,'-UnityPath',$UnityPath);Write-Checkpoint 'compile-passed' $null
 Invoke-Step '03-memory-policy-self-test' (Join-Path $ProjectPath 'Research\Verification\Run-Gate13RPR1BMemoryPolicySelfTestV2.ps1') @('-ProjectPath',$ProjectPath,'-VerificationRoot',$root,'-UnityPath',$UnityPath);Write-Checkpoint 'memory-policy-self-test-passed' $null
 $telemetryOutput=Join-Path $root 'TelemetryProbe\v2';Invoke-Step '04-telemetry' (Join-Path $ProjectPath 'Research\Run-Gate13RPR1BMemoryTelemetryProbeV2.ps1') @('-ProjectPath',$ProjectPath,'-OutputDirectory',$telemetryOutput,'-AllowedRoot',$root,'-UnityPath',$UnityPath);$telemetryResult=Join-Path $telemetryOutput 'telemetry-probe-result.json';Write-Checkpoint 'telemetry-passed' $null
 Invoke-Step '05-block-verification' (Join-Path $ProjectPath 'Research\Verification\Run-Gate13RPR1BBlockVerificationV2.ps1') @('-ProjectPath',$ProjectPath,'-VerificationRoot',$root,'-PilotPlanPath',$PilotPlanPath,'-ProvenancePath',$ProvenancePath,'-TelemetryResultPath',$telemetryResult,'-UnityPath',$UnityPath);Write-Checkpoint 'block-repeatability-cold-retained-passed' $null
 Invoke-Step '06-validation-only-audit' (Join-Path $ProjectPath 'Research\Verification\Run-Gate13RPR1BValidationOnlyPrePilotAuditV2.ps1') @('-ProjectPath',$ProjectPath,'-VerificationRoot',$root,'-PilotPlanPath',$PilotPlanPath,'-ProvenancePath',$ProvenancePath,'-TelemetryResultPath',$telemetryResult);$audit=Read-Gate13RPR1BV2Json (Join-Path $root 'ValidationOnlyPrePilotAudit.summary.json');if($audit.passed-ne$true-or$audit.pilotExecutionAuthorized-ne$true){throw 'Final PR1B v2 validation-only audit did not authorize pilot execution.'}
 Write-Checkpoint 'PREPILOT-PASSED-PILOT-AUTHORIZED' $null;Write-Partial 'PREPILOT-PASSED-PILOT-AUTHORIZED';Write-Host 'PR1B v2 pre-pilot gates passed.' -ForegroundColor Green;exit 0
}catch{$message=$_.Exception.ToString();$failure=[ordered]@{schemaVersion=2;receiptKind='gate13r-pr1b-v2-prepilot-failure-receipt-v1';failedAtUtc=[DateTime]::UtcNow.ToString('o');message=$message;status='FAILED-NO-PILOT';formalCampaign=$false;gate13rFormalAuthorized=$false};Write-Gate13RPR1BV2AtomicUtf8NoBomJson -Path (Join-Path $root 'failure-receipt.json') -Value $failure -Depth 15;Write-Checkpoint 'failed-no-pilot' $message;Write-Partial 'failed-no-pilot';Write-Error "PR1B v2 pre-pilot failed closed: $message";exit 1}
